import 'package:flutter/material.dart';
import 'package:flutter_localizations/flutter_localizations.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

// Generated by flutter gen-l10n
import '../l10n/app_localizations.dart';
import '../navigation/app_router.dart';
import 'theme.dart';

/// Root widget of the Sahaayi application.
///
/// Sets up:
/// - [MaterialApp.router] with [go_router] navigation.
/// - Light and dark [ThemeData] tuned for accessibility.
/// - Localisation delegates supporting Malayalam and English.
class SahaayiApp extends ConsumerWidget {
  const SahaayiApp({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final router = ref.watch(appRouterProvider);

    return MaterialApp.router(
      // ── Identity ──────────────────────────────────────────────────────────
      title: 'Sahaayi',
      debugShowCheckedModeBanner: false,

      // ── Routing ───────────────────────────────────────────────────────────
      routerConfig: router,

      // ── Theming ───────────────────────────────────────────────────────────
      theme: SahaayiTheme.lightTheme,
      darkTheme: SahaayiTheme.lightTheme,
      themeMode: ThemeMode.light,

      // ── Localisation ──────────────────────────────────────────────────────
      localizationsDelegates: const [
        AppLocalizations.delegate,
        GlobalMaterialLocalizations.delegate,
        GlobalWidgetsLocalizations.delegate,
        GlobalCupertinoLocalizations.delegate,
      ],
      supportedLocales: const [
        Locale('en'), // English
        Locale('ml'), // Malayalam
      ],
      locale: const Locale('ml'), // Default to Malayalam for target audience

      // ── Accessibility ─────────────────────────────────────────────────────
      // Increase base text scale factor floor so elderly users always see
      // at least the design-spec minimum size, regardless of system setting.
      builder: (context, child) {
        final mediaQuery = MediaQuery.of(context);
        return MediaQuery(
          data: mediaQuery.copyWith(
            textScaler: TextScaler.linear(
              mediaQuery.textScaler.scale(1.0).clamp(1.0, 1.4),
            ),
          ),
          child: child!,
        );
      },
    );
  }
}
